function binarySearch(nums, target) {
  let low = 0;
  let high = nums.length - 1;
  while (low <= high) {
    const mid = low + Math.floor((high - low) / 2);
    if (nums[mid] === target) return mid;
    if (nums[mid] < target) low = mid + 1;   // the target is to the right
    else high = mid - 1;                     // the target is to the left
  }
  return -1;
}

def binary_search(nums, target):
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2           # Python's ints can't overflow
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            low = mid + 1                 # the target is to the right
        else:
            high = mid - 1                # the target is to the left
    return -1

int binarySearch(int[] nums, int target) {
    int low = 0, high = nums.length - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;   // (low + high) / 2 can overflow
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) low = mid + 1;   // the target is to the right
        else high = mid - 1;                     // the target is to the left
    }
    return -1;
}

int binarySearch(vector<int>& nums, int target) {
    int low = 0, high = (int)nums.size() - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;   // (low + high) / 2 can overflow
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) low = mid + 1;   // the target is to the right
        else high = mid - 1;                     // the target is to the left
    }
    return -1;
}

function binarySearchRecursive(nums, target, low = 0, high = nums.length - 1) {
  if (low > high) return -1;                          // empty range: not there
  const mid = low + Math.floor((high - low) / 2);
  if (nums[mid] === target) return mid;
  if (nums[mid] < target) return binarySearchRecursive(nums, target, mid + 1, high);
  return binarySearchRecursive(nums, target, low, mid - 1);
}

def binary_search_recursive(nums, target, low=0, high=None):
    if high is None:
        high = len(nums) - 1
    if low > high:
        return -1                         # empty range: not there
    mid = (low + high) // 2
    if nums[mid] == target:
        return mid
    if nums[mid] < target:
        return binary_search_recursive(nums, target, mid + 1, high)
    return binary_search_recursive(nums, target, low, mid - 1)

int binarySearchRecursive(int[] nums, int target) {
    return search(nums, target, 0, nums.length - 1);
}

int search(int[] nums, int target, int low, int high) {
    if (low > high) return -1;                        // empty range: not there
    int mid = low + (high - low) / 2;
    if (nums[mid] == target) return mid;
    if (nums[mid] < target) return search(nums, target, mid + 1, high);
    return search(nums, target, low, mid - 1);
}

int search(vector<int>& nums, int target, int low, int high) {
    if (low > high) return -1;                        // empty range: not there
    int mid = low + (high - low) / 2;
    if (nums[mid] == target) return mid;
    if (nums[mid] < target) return search(nums, target, mid + 1, high);
    return search(nums, target, low, mid - 1);
}

int binarySearchRecursive(vector<int>& nums, int target) {
    return search(nums, target, 0, (int)nums.size() - 1);
}
